--
-- Table structure for table `product_comment_ratings`
--

DROP TABLE IF EXISTS `product_comment_ratings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_comment_ratings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `customer_id` bigint unsigned NOT NULL,
  `comment` text COLLATE utf8mb4_unicode_ci,
  `likes` int unsigned DEFAULT '0',
  `dislikes` int unsigned DEFAULT '0',
  `is_approved` tinyint(1) NOT NULL DEFAULT '0',
  `rating` tinyint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_comment_ratings_product_id_foreign` (`product_id`),
